<script setup lang="ts">
import ProgramTeam from './components/ProgramTeam.vue';
import GuidanceMessages from './components/GuidanceMessages.vue';
const teamDialog=ref(false),teamId=ref(''),messageDialog=ref(false);
import BusinessPageHeader from '#/components/BusinessPageHeader.vue';
import ProgramFeedback from './components/ProgramFeedback.vue';
const feedbackDialog=ref(false),feedbackId=ref('');
import CourseLessons from './components/CourseLessons.vue';
const courseDialog=ref(false),courseId=ref('');
import {useRoute} from 'vue-router';
const route=useRoute();
import { computed, onMounted, reactive, ref, watch } from 'vue';
import { ElButton, ElCard, ElDialog, ElDropdown, ElDropdownItem, ElDropdownMenu, ElForm, ElFormItem, ElInput, ElInputNumber, ElSelect, ElOption, ElDatePicker, ElTable, ElTableColumn, ElTag, ElMessage, ElMessageBox } from 'element-plus';
import { requestClient } from '#/api/request';
import { confirmAction } from '#/utils/confirm-action';
import { allowedStatuses } from './programs-status';
import DataErrorBanner from '#/components/data-state/DataErrorBanner.vue';
import DataState from '#/components/data-state/DataState.vue';
import TablePagination from '#/components/table-pagination/TablePagination.vue';
type Program = { id:string;kind:string;title:string;description:string;location:string;co_leader:string;materials:string;start_time:string;end_time:string;capacity:number;status:string;booked:number };
type Attendee={id:string;nickname:string;status:string};
const rows=ref<Program[]>([]),loading=ref(false),saving=ref(false),error=ref(''),query=ref(''),dialog=ref(false),selected=ref(''),attendeeDialog=ref(false),attendees=ref<Attendee[]>([]),attendeeProgram=ref(''),checking=ref('');
const attendeeLoading=ref(false),attendeeError=ref(''),attendeeTitle=ref('');
const pendingCount=computed(()=>attendees.value.filter(a=>a.status==='PENDING').length);
const statusFilter=ref('ALL');const kindFilter=ref(['WORKSHOP','COURSE','GUIDANCE'].includes(String(route.query.kind))?String(route.query.kind):'ALL');
const statusCards=computed(()=>[{id:'ALL',label:'当前列表',count:rows.value.length},...['DRAFT','PUBLISHED','CANCELLED'].map(id=>({id,label:id==='DRAFT'?'待完善草稿':id==='PUBLISHED'?'已发布':'已取消',count:rows.value.filter(p=>p.status===id).length}))]);
const names:Record<string,string>={WORKSHOP:'主题工作坊',COURSE:'系列课程',GUIDANCE:'一对一指导',DRAFT:'草稿',PUBLISHED:'已发布',CANCELLED:'已取消',PENDING:'待确认',REJECTED:'未通过',BOOKED:'已确认 / 待签到',CHECKED_IN:'已签到'};
const form=reactive({kind:'WORKSHOP',title:'',description:'',location:'',coLeader:'',materials:'',startTime:'',endTime:'',capacity:12,status:'DRAFT'});
const visible=computed(()=>rows.value.filter(p=>(kindFilter.value==='ALL'||p.kind===kindFilter.value)&&(statusFilter.value==='ALL'||p.status===statusFilter.value)&&`${p.title} ${p.location}`.includes(query.value.trim())));
const page=ref(1);
const pageSize=10;
const emptyText='暂无活动，创建草稿后可发布';
const pagedRows=computed(()=>visible.value.slice((page.value-1)*pageSize,page.value*pageSize));
const editingStatus=ref('DRAFT');
watch([kindFilter,statusFilter,query],()=>{page.value=1});
async function load(){loading.value=true;error.value='';try{rows.value=await requestClient.get('/growth/programs/manage')}catch{error.value='加载失败，请重试。'}finally{loading.value=false}}
function edit(p?:Program){editingStatus.value=p?.status??'DRAFT';selected.value=p?.id||'';Object.assign(form,p?{kind:p.kind,title:p.title,description:p.description,location:p.location,coLeader:p.co_leader,materials:p.materials,startTime:p.start_time,endTime:p.end_time,capacity:p.capacity,status:p.status}:{kind:'WORKSHOP',title:'',description:'',location:'',coLeader:'',materials:'',startTime:'',endTime:'',capacity:12,status:'DRAFT'});dialog.value=true}
async function template(){if(form.description&&!(await confirmAction({confirmText:'替换',message:'用八周课程结构替换当前课程说明？现有说明会被覆盖。',title:'替换课程说明'})))return;form.kind='COURSE';form.description='第 1 周：认识材料与安全约定\n第 2 周：感官觉察与基础技法\n第 3 周：以色彩表达当下\n第 4 周：体验节奏与重复\n第 5 周：纹样与个人故事\n第 6 周：合作创作与边界\n第 7 周：整理作品与回看\n第 8 周：分享与后续计划\n\n请补充每周实际日期、地点、带领者与所需材料。课程不替代专业心理咨询。'}
async function save(){if(saving.value)return;if(!form.title.trim()||!form.description.trim()||!form.location.trim()||!form.startTime||!form.endTime){ElMessage.warning('请填写标题、说明、地点和完整日程');return}if(form.endTime<=form.startTime){ElMessage.warning('结束时间须晚于开始时间');return}if(form.status==='CANCELLED'&&editingStatus.value!=='CANCELLED'){const confirmed=await confirmAction({confirmText:'取消活动',danger:true,message:'取消后用户会看到已取消状态，且无法恢复到发布状态。',title:'取消活动'});if(!confirmed)return}saving.value=true;try{const body={...form,capacity:form.kind==='GUIDANCE'?1:form.capacity};if(selected.value)await requestClient.put(`/growth/programs/${selected.value}`,body);else await requestClient.post('/growth/programs',body);dialog.value=false;ElMessage.success('已保存');await load()}catch{/* shared request handler displays API error */}finally{saving.value=false}}
async function showAttendees(p:Program){attendees.value=[];attendeeProgram.value=p.id;attendeeTitle.value=p.title;attendeeDialog.value=true;await reloadAttendees()}
async function reloadAttendees(){attendeeLoading.value=true;attendeeError.value='';try{attendees.value=await requestClient.get('/growth/programs/'+attendeeProgram.value+'/attendees')}catch{attendeeError.value='报名名单加载失败，请重试'}finally{attendeeLoading.value=false}}
async function review(a:Attendee,decision:'CONFIRM'|'REJECT'){
 if(checking.value)return;
 try{await ElMessageBox.confirm(decision==='CONFIRM'?'确认接受这条一对一预约？':'拒绝后将释放名额，用户会看到未通过状态。',decision==='CONFIRM'?'确认预约':'拒绝预约',{type:decision==='CONFIRM'?'info':'warning'});checking.value=a.id;await requestClient.post('/growth/programs/'+attendeeProgram.value+'/bookings/'+a.id+'/review',{decision});ElMessage.success(decision==='CONFIRM'?'预约已确认':'已拒绝并释放名额');await reloadAttendees();await load()}catch{/* request handler shows server errors */}finally{checking.value=''}
}
async function checkin(a:Attendee){if(checking.value)return;try{await ElMessageBox.confirm(`确认为 ${a.nickname} 签到？`,'签到确认');checking.value=a.id;await requestClient.post(`/growth/programs/${attendeeProgram.value}/checkin`,{bookingId:a.id});a.status='CHECKED_IN';ElMessage.success('签到成功')}catch{}finally{checking.value=''}}
onMounted(load);
</script>
<template><div class="zy-business-page"><BusinessPageHeader eyebrow="PROGRAM OPERATIONS" title="活动与预约管理" description="安排工作坊与课程，及时处理一对一申请，让每一次相聚都有清晰的下一步。"><ElButton @click="messageDialog=true">本人预约交流</ElButton><ElButton type="primary" @click="edit()">新建活动</ElButton></BusinessPageHeader><div class="status-cards"><button v-for="card in statusCards" :key="card.id" :class="{active:statusFilter===card.id}" :aria-pressed="statusFilter===card.id" @click="statusFilter=card.id"><span>{{card.label}}</span><strong>{{loading?'—':card.count}}</strong></button></div><DataErrorBanner v-if="error" :error="error" :retrying="loading" @retry="load"/><ElCard shadow="never"><div class="toolbar"><ElSelect v-model="kindFilter" style="width:150px" aria-label="活动类型"><ElOption value="ALL" label="全部类型"/><ElOption v-for="k in ['WORKSHOP','COURSE','GUIDANCE']" :key="k" :value="k" :label="names[k]"/></ElSelect><ElInput v-model="query" placeholder="搜索标题或地点" clearable style="max-width:320px"/><ElButton :loading="loading" @click="load">刷新</ElButton><span>{{visible.length}} 项 · 北京时间</span></div><ElTable v-loading="loading" :data="pagedRows" stripe><template #empty><DataState :loading="loading" :error="error" :empty-text="emptyText" empty-hint="点击「新建活动」开始创建" @retry="load"/></template><ElTableColumn prop="title" label="活动名称" min-width="200"/><ElTableColumn label="类型" min-width="120"><template #default="{row}">{{names[row.kind]}}</template></ElTableColumn><ElTableColumn label="开始时间" min-width="170"><template #default="{row}">{{row.start_time.replace('T',' ').slice(0,16)}}</template></ElTableColumn><ElTableColumn label="报名" width="90"><template #default="{row}">{{row.booked}} / {{row.capacity}}</template></ElTableColumn><ElTableColumn label="状态" width="110"><template #default="{row}"><ElTag :type="row.status==='PUBLISHED'?'success':row.status==='CANCELLED'?'danger':'info'">{{names[row.status]}}</ElTag></template></ElTableColumn><ElTableColumn label="操作" width="200" fixed="right"><template #default="{row}"><ElButton link type="primary" @click="edit(row as Program)">编辑</ElButton><ElButton link type="primary" @click="showAttendees(row as Program)">报名与签到</ElButton><ElDropdown trigger="click"><ElButton link type="primary">更多</ElButton><template #dropdown><ElDropdownMenu><ElDropdownItem v-if="row.kind==='COURSE'" @click="courseId=row.id;courseDialog=true">课节</ElDropdownItem><ElDropdownItem @click="feedbackId=row.id;feedbackDialog=true">反馈</ElDropdownItem><ElDropdownItem v-if="row.kind!=='GUIDANCE'" @click="teamId=row.id;teamDialog=true">协作团队</ElDropdownItem></ElDropdownMenu></template></ElDropdown></template></ElTableColumn></ElTable><TablePagination v-model:page="page" :page-size="10" :total="visible.length"/></ElCard><p class="foot">本系统不能替代专业心理咨询</p>
<ElDialog v-model="teamDialog" title="协作团队权限" width="min(650px,94vw)" destroy-on-close><ProgramTeam v-if="teamDialog" :program-id="teamId"/></ElDialog><ElDialog v-model="messageDialog" title="本人预约交流" width="min(960px,96vw)" destroy-on-close><GuidanceMessages v-if="messageDialog"/></ElDialog><ElDialog v-model="dialog" :title="selected?'编辑活动':'新建活动'" width="min(720px, 94vw)" :close-on-click-modal="false" :show-close="!saving" :close-on-press-escape="!saving"><ElForm label-position="top"><div class="form-grid"><ElFormItem label="活动类型"><ElSelect v-model="form.kind"><ElOption v-for="k in ['WORKSHOP','COURSE','GUIDANCE']" :key="k" :label="names[k]" :value="k"/></ElSelect></ElFormItem><ElFormItem label="发布状态"><ElSelect v-model="form.status" :disabled="allowedStatuses(editingStatus).length===1"><ElOption v-for="s in allowedStatuses(editingStatus)" :key="s" :label="names[s]" :value="s"/></ElSelect></ElFormItem></div><ElFormItem label="活动标题"><ElInput v-model="form.title" maxlength="100" show-word-limit/></ElFormItem><ElFormItem label="内容与安排"><ElInput v-model="form.description" type="textarea" :rows="6" maxlength="6000"/><ElButton link type="primary" @click="template">填入八周课程结构</ElButton></ElFormItem><div class="form-grid"><ElFormItem label="开始时间（北京时间）"><ElDatePicker v-model="form.startTime" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" style="width:100%"/></ElFormItem><ElFormItem label="结束时间（北京时间）"><ElDatePicker v-model="form.endTime" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" style="width:100%"/></ElFormItem></div><ElFormItem label="地点或参与方式"><ElInput v-model="form.location" maxlength="200"/></ElFormItem><div class="form-grid"><ElFormItem label="协同带领者（选填）"><ElInput v-model="form.coLeader" maxlength="100"/></ElFormItem><ElFormItem label="名额（一对一固定为 1）"><ElInputNumber v-model="form.capacity" :min="1" :max="200" :disabled="form.kind==='GUIDANCE'"/></ElFormItem></div><ElFormItem label="准备材料（选填）"><ElInput v-model="form.materials" type="textarea" maxlength="1000"/></ElFormItem><ElAlert title="已有报名后不能修改日程或类型；需要调整时请取消原活动并发布新活动。" type="info" :closable="false"/></ElForm><template #footer><ElButton :disabled="saving" @click="dialog=false">取消</ElButton><ElButton type="primary" :loading="saving" @click="save">保存</ElButton></template></ElDialog>
<ElDialog v-model="attendeeDialog" title="预约处理中心" width="min(760px, 94vw)" :close-on-click-modal="!checking"><div class="booking-summary"><div><span class="eyebrow">{{attendeeTitle}}</span><h2>{{pendingCount}} 条待确认申请</h2><p>一对一申请需确认后才能签到。待确认申请会占用名额。</p></div><ElButton :loading="attendeeLoading" :disabled="!!checking" @click="reloadAttendees">刷新名单</ElButton></div><ElAlert v-if="attendeeError" :title="attendeeError" type="error" :closable="false" show-icon/><ElAlert title="签到时间：开始前 30 分钟至结束后 24 小时。此处仅展示报名昵称。" :closable="false"/><ElTable v-loading="attendeeLoading" :data="attendees" empty-text="暂无预约记录，发布后可邀请学生报名"><ElTableColumn prop="nickname" label="参加者" min-width="140"/><ElTableColumn label="预约状态" min-width="160"><template #default="{row}"><ElTag :type="row.status==='PENDING'?'warning':row.status==='BOOKED'||row.status==='CHECKED_IN'?'success':'info'">{{names[row.status]||row.status}}</ElTag></template></ElTableColumn><ElTableColumn label="下一步操作" min-width="220"><template #default="{row}"><template v-if="row.status==='PENDING'"><ElButton type="primary" :loading="checking===row.id" :disabled="!!checking" @click="review(row as Attendee,'CONFIRM')">确认预约</ElButton><ElButton type="danger" plain :disabled="!!checking" @click="review(row as Attendee,'REJECT')">拒绝</ElButton></template><ElButton v-else-if="row.status==='BOOKED'" type="primary" link :loading="checking===row.id" :disabled="!!checking" @click="checkin(row as Attendee)">确认签到</ElButton><span v-else class="settled">无需处理</span></template></ElTableColumn></ElTable></ElDialog><ElDialog v-model="feedbackDialog" title="活动反馈汇总" width="min(720px,94vw)" destroy-on-close><ProgramFeedback v-if="feedbackDialog" :program-id="feedbackId"/></ElDialog><ElDialog v-model="courseDialog" title="课程章节" width="min(850px, 96vw)" destroy-on-close><CourseLessons v-if="courseDialog" :program-id="courseId"/></ElDialog></div></template>
<style scoped>.booking-summary{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:20px;background:var(--el-color-primary-light-9);border-radius:14px;margin-bottom:20px}.booking-summary h2{font-size:24px;font-weight:650;margin:10px 0}.booking-summary p{margin:0;font-size:13px}.settled{color:var(--el-text-color-secondary);font-size:13px}.status-cards{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:24px}.status-cards button{display:flex;flex-direction:column;gap:12px;align-items:flex-start;background:var(--el-bg-color);padding:20px;border:1px solid var(--el-border-color);border-radius:12px;transition:transform .15s,border-color .15s;color:var(--el-text-color-regular);cursor:pointer}.status-cards button.active{border-color:var(--el-color-primary);background:var(--el-color-primary-light-9)}.status-cards strong{font-size:26px}.status-cards button:active{transform:scale(.98)}.status-cards button:focus-visible{outline:2px solid var(--el-color-primary);outline-offset:3px}@media(max-width:600px){.status-cards{grid-template-columns:repeat(2,1fr);gap:10px}}@media(prefers-reduced-motion:reduce){.status-cards button{transition:none;transform:none!important}}.eyebrow{color:var(--el-color-primary);font-size:11px;letter-spacing:2px}.toolbar{display:flex;gap:12px;align-items:center;margin-bottom:20px;flex-wrap:wrap}.toolbar span,.foot{font-size:12px;color:var(--el-text-color-secondary)}.foot{margin-top:24px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}@media(max-width:600px){.form-grid{grid-template-columns:1fr;gap:0}}</style>
